import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)
    sink = m - 1

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    INF = 10**18
    h = [INF] * m
    h[0] = 0
    for u in range(m):
        hu = h[u]
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and hu + cost < h[v]:
                h[v] = hu + cost

    rem = k
    total_cost = 0

    while rem > 0:
        dist = [INF] * m
        parent_v = [-1] * m
        parent_e = [-1] * m
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d != dist[u]:
                continue
            hu = h[u]
            for ei, e in enumerate(adj[u]):
                if e[1] > 0:
                    v = e[0]
                    nd = d + e[2] + hu - h[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for v in range(m):
            if dist[v] < INF:
                h[v] += dist[v]

        if h[sink] >= 0:
            break

        flow = rem
        v = sink
        while v != 0:
            u = parent_v[v]
            cap = adj[u][parent_e[v]][1]
            if cap < flow:
                flow = cap
            v = u

        v = sink
        while v != 0:
            u = parent_v[v]
            e = adj[u][parent_e[v]]
            e[1] -= flow
            adj[v][e[3]][1] += flow
            v = u

        rem -= flow
        total_cost += flow * h[sink]

    return -total_cost
